[SysAppEntity(tableStr(FMRentalCharge), methodStr(FMRentalChargeListItem, recId))]
class FMRentalChargeListItem
{
    private str descriptionInternal;
    private FMRentalChargeType rentalChargeTypeInternal;
    private int64 recIdInternal;
    private real unitAmountInternal;

}

Method.Source:
[SysAppField(fieldStr(FMRentalCharge, Description), "Description")]
public str description(str _value=descriptionInternal)
{
    descriptionInternal = _value;
    return descriptionInternal;
}

[SysAppField(fieldStr(FMRentalCharge, ChargeType ), "Charge type")]
public FMRentalChargeType rentalChargeType(FMRentalChargeType _value=rentalChargeTypeInternal)
{
    rentalChargeTypeInternal = _value;
    return rentalChargeTypeInternal;
}

[SysAppField(fieldStr(FMRentalCharge, PerUnitAmount), "Per unit amount")]
public real unitAmount(real _value=unitAmountInternal)
{
    unitAmountInternal = _value;
    return unitAmountInternal;
}

[SysAppField(fieldStr(FMRentalCharge, RecId), "RecId")]
public int64 recId(int64 _value=recIdInternal)
{
    recIdInternal = _value;
    return recIdInternal;
}

public static FMRentalChargeListItem getRentalChargeDetails(SysAppEntityContext _entityContext, List _filterContextList)
{
    if (_entityContext && _entityContext.entityId())
    {
        int64 recId = str2Int64(_entityContext.entityId());

        FMRentalCharge rentalCharge;
        select firstonly * from rentalCharge
            where rentalCharge.RecId == recId;

        FMRentalChargeListItem rentalChargeItem = new FMRentalChargeListItem();
        rentalChargeItem.populate(rentalCharge);

        return rentalChargeItem;
    }
    else
    {
        return null;
    }
}
